<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
const DEFAULT_INNER_GRADIENT='linear-gradient(145deg,#60496e8c 0%,#71C4FF44 100%)';
const ANIMATION_CONFIG={INITIAL_DURATION:1200,INITIAL_X_OFFSET:70,INITIAL_Y_OFFSET:60,DEVICE_BETA_OFFSET:20,ENTER_TRANSITION_MS:180} as const;
interface Props{avatarUrl?:string;iconUrl?:string;grainUrl?:string;innerGradient?:string;behindGlowEnabled?:boolean;behindGlowColor?:string;behindGlowSize?:string;className?:string;enableTilt?:boolean;enableMobileTilt?:boolean;mobileTiltSensitivity?:number;miniAvatarUrl?:string;name?:string;title?:string;handle?:string;status?:string;contactText?:string;showUserInfo?:boolean;}
const props=withDefaults(defineProps<Props>(),{avatarUrl:'',iconUrl:'',grainUrl:'',behindGlowEnabled:false,className:'',enableTilt:true,enableMobileTilt:false,mobileTiltSensitivity:5,name:'',title:'',handle:'',status:'',contactText:'Contact',showUserInfo:true});
const emit=defineEmits<{contactClick:[]}>();
const wrapRef=ref<HTMLDivElement|null>(null),shellRef=ref<HTMLDivElement|null>(null),enterTimerRef=ref<number|null>(null),leaveRafRef=ref<number|null>(null);
let tiltEngine:ReturnType<typeof createTiltEngine>|null=null;
function createTiltEngine(){let rafId:number|null=null,running=false,lastTs=0,currentX=0,currentY=0,targetX=0,targetY=0,initialUntil=0;const DEFAULT_TAU=.14,INITIAL_TAU=.6;const clamp=(v:number,min=0,max=100)=>Math.min(Math.max(v,min),max),round=(v:number,precision=3)=>parseFloat(v.toFixed(precision)),adjust=(v:number,fMin:number,fMax:number,tMin:number,tMax:number)=>round(tMin+((tMax-tMin)*(v-fMin))/(fMax-fMin));
const setVarsFromXY=(x:number,y:number)=>{const shell=shellRef.value,wrap=wrapRef.value;if(!shell||!wrap)return;const width=shell.clientWidth||1,height=shell.clientHeight||1,percentX=clamp(100/width*x),percentY=clamp(100/height*y),centerX=percentX-50,centerY=percentY-50;const properties:Record<string,string>={'--pointer-x':`${percentX}%`,'--pointer-y':`${percentY}%`,'--background-x':`${adjust(percentX,0,100,35,65)}%`,'--background-y':`${adjust(percentY,0,100,35,65)}%`,'--pointer-from-center':`${clamp(Math.hypot(percentY-50,percentX-50)/50,0,1)}`,'--pointer-from-top':`${percentY/100}`,'--pointer-from-left':`${percentX/100}`,'--rotate-x':`${round(-(centerX/5))}deg`,'--rotate-y':`${round(centerY/4)}deg`};for(const[k,v]of Object.entries(properties))wrap.style.setProperty(k,v);};
const step=(ts:number)=>{if(!running)return;if(lastTs===0)lastTs=ts;const dt=(ts-lastTs)/1000;lastTs=ts;const tau=ts<initialUntil?INITIAL_TAU:DEFAULT_TAU,k=1-Math.exp(-dt/tau);currentX+=(targetX-currentX)*k;currentY+=(targetY-currentY)*k;setVarsFromXY(currentX,currentY);const stillFar=Math.abs(targetX-currentX)>.05||Math.abs(targetY-currentY)>.05;if(stillFar||ts<initialUntil){rafId=requestAnimationFrame(step);}else{running=false;lastTs=0;rafId=null;}};
const start=()=>{if(running)return;running=true;lastTs=0;rafId=requestAnimationFrame(step);};return{setImmediate(x:number,y:number){currentX=x;currentY=y;setVarsFromXY(currentX,currentY);},setTarget(x:number,y:number){targetX=x;targetY=y;start();},toCenter(){const shell=shellRef.value;if(shell)this.setTarget(shell.clientWidth/2,shell.clientHeight/2);},beginInitial(durationMs:number){initialUntil=performance.now()+durationMs;start();},getCurrent(){return{x:currentX,y:currentY,tx:targetX,ty:targetY};},cancel(){if(rafId!==null)cancelAnimationFrame(rafId);rafId=null;running=false;lastTs=0;}};}
const getOffsets=(evt:PointerEvent,el:HTMLElement)=>{const rect=el.getBoundingClientRect();return{x:evt.clientX-rect.left,y:evt.clientY-rect.top};};
