const handlePointerLeave=()=>{const shell=shellRef.value;if(!shell||!tiltEngine||!props.enableTilt)return;tiltEngine.toCenter();const checkSettle=()=>{if(!tiltEngine){leaveRafRef.value=null;return;}const{x,y,tx,ty}=tiltEngine.getCurrent();if(Math.hypot(tx-x,ty-y)<.6){shell.classList.remove('active');leaveRafRef.value=null;}else leaveRafRef.value=requestAnimationFrame(checkSettle);};if(leaveRafRef.value!==null)cancelAnimationFrame(leaveRafRef.value);leaveRafRef.value=requestAnimationFrame(checkSettle);};
