</script>
<template>
<div ref="wrapRef" :class="`pc-card-wrapper ${className}`.trim()" :style="cardStyle"><div ref="shellRef" class="pc-card-shell"><section class="pc-card"><div class="pc-inside"><div class="pc-content pc-avatar-content"><img class="avatar" :src="avatarUrl" :alt="`${name || 'User'} avatar`" loading="eager" decoding="async" @error="handleAvatarError"/><div v-if="showUserInfo" class="pc-user-info"><div class="pc-user-details"><div class="pc-mini-avatar"><img :src="miniAvatarUrl || avatarUrl" :alt="`${name || 'User'} mini avatar`" loading="lazy" @error="handleMiniAvatarError"/></div><div class="pc-user-text"><div class="pc-handle">@{{handle}}</div><div class="pc-status">{{status}}</div></div></div><button class="pc-contact-btn" @click="handleContactClick" style="pointer-events:auto" type="button" :aria-label="`Contact ${name || 'user'}`">{{contactText}}</button></div></div><div class="pc-content"><div class="pc-details"><h3>{{name}}</h3><p>{{title}}</p></div></div></div></section></div></div>
</template>
<style scoped>
