.pc-card-shell{position:relative;z-index:1}.pc-card{height:80svh;max-height:540px;display:grid;aspect-ratio:.718;border-radius:var(--card-radius);position:relative;box-shadow:rgba(0,0,0,.8) calc((var(--pointer-from-left) * 10px) - 3px) calc((var(--pointer-from-top) * 20px) - 6px) 20px -5px;transition:transform 1s ease;transform:translateZ(0) rotateX(0deg) rotateY(0deg);background:rgba(0,0,0,.9);backface-visibility:hidden;overflow:hidden}.pc-card:hover,.pc-card.active,.pc-card-shell.active .pc-card{transition:none;transform:translateZ(0) rotateX(var(--rotate-y)) rotateY(var(--rotate-x))}.pc-card-shell.entering .pc-card{transition:transform 180ms ease-out}.pc-card *{display:grid;grid-area:1/-1;border-radius:var(--card-radius);pointer-events:none}.pc-inside{inset:0;position:absolute;background-image:var(--inner-gradient);background-color:rgba(0,0,0,.9);transform:none}
